import{Helper}from"../Helper";import{FSConfig}from"../index";import{PageManager}from"./PageManager";let _instance=null;function getInstance(){if(null!==_instance){return _instance}_instance={buildQueryString:function(data){const params=[];for(let key in data){if(!data.hasOwnProperty(key)){continue}params.push(encodeURIComponent(key)+"="+encodeURIComponent(data[key]))}return params.join("&")},request:function(url,data){data={...data,...FSConfig};return fetch(PageManager.getInstance().addQueryArgs(url,data),{method:"GET",headers:{"Content-Type":"application/json"}}).then(response=>{let jsonResponse=response.json();if(jsonResponse.success&&Helper.isNonEmptyString(jsonResponse.next_page)){window.location.href=jsonResponse.next_page}return jsonResponse})}};return _instance}export const RequestManager={getInstance:function(){return getInstance()}};